        kx, ky = locate_avg(k)
        mx, my = locate_avg(m)
        dx, dy = kx-mx, ky-my
        dist = (dx*dx+dy*dy)**0.5
        print(f"{k} attempt {attempt}: dx={dx:+.3f} dy={dy:+.3f} dist={dist:.3f}")
        if dist < 0.06:
            break
        # nudge opposite to offset; scale slightly under to avoid overshoot
        ndx, ndy = -dx, -dy
        r = workcell.robot("nudge", k, f"{ndx:.3f}", f"{ndy:.3f}")
        print(" ", r.text)
